CHAINS=[{'chain': '600187-扣非更正，是否又亏了一笔钱', 'source': '1225483477', 'pages': [1, 2], 'subject': '扣非更正，是否又亏了一笔钱', 'changed': '8月将2025年长期股权投资减值从非经常项目剔除，2025扣非由-59762087.53元改为-214628790.66元。', 'open': '这是旧年度损益分类更正，公告明确总资产、归母净资产、归母净利润及经营现金不变；不当2026新发生亏损或现金流出，也不倒填7月3日已知。', 'supporting': []}, {'chain': '600187-旧案撤诉后，为何仍不能关闭汇源风险', 'source': '1225464090', 'pages': [1, 2], 'subject': '旧案撤诉后，为何仍不能关闭汇源风险', 'changed': '7月法院准许（2025）京03民初2237号旧案撤诉；8月另披露（2026）京03民初174号新案，诉请913518166.67元，诸暨文盛汇所持北京汇源60%股权被保全冻结。', 'open': '旧案撤诉不等于新案终结或全部解冻。被冻结的是参股平台持有的底层股权，不是上市公司60%股权；原告诉请不当公司已确认损失。10月仍无完整可靠底层财务信息，秦皇岛事项另核。', 'supporting': [{'source': '1225426745', 'pages': [1, 2], 'state': '旧案7月6日申请撤诉、14日收到裁定，16日披露；解冻仍待推进。'}, {'source': '1225649550', 'pages': [2], 'state': '10月31日仍披露轮候冻结、案件未开庭和取证缺口。'}]}, {'chain': '600187-收入增长，半年微利为何未持续', 'source': '1225649540', 'pages': [1], 'subject': '收入增长，半年微利为何未持续', 'changed': '半年归母盈利2902908.56元，前三季归母转为-3763038.68元，扣非累计-19986430.15元；收入累计增长但未保持盈利。', 'open': '季度现金9285619.90元为累计减半年推算，累计现金仍负4577647.65元。未经审计期报不代替年度扣除后营收、审计取证及内控条件。', 'supporting': [{'source': '1225485841', 'pages': [6], 'state': '半年归母微利、扣非和经营现金仍负。'}]}, {'chain': '600238-摘星已经落地，为什么仍叫ST', 'source': '1225448701', 'pages': [1, 3], 'subject': '摘星已经落地，为什么仍叫ST', 'changed': '7月30日获准撤销退市风险警示，31日停牌，8月3日起由*ST椰岛改为ST椰岛。', 'open': '持续经营与内控相关其他风险警示继续，仍在风险警示板、涨跌幅仍10%。不是全部摘帽，也不是这一天才5改10；7月31日没有成交收益，空值保持。三季度亏损、累计经营现金流出另看。', 'supporting': [{'source': '1225645540', 'pages': [1, 2], 'state': '10月仍有其他风险警示，旧非标事项消除与警示规则分开。'}]}, {'chain': '600238-拿酒抵债，签约是否等于已经结案', 'source': '1225469364', 'pages': [2, 3], 'subject': '拿酒抵债，签约是否等于已经结案', 'changed': '子公司拟以900万元酒类产品抵偿生效判决债务，足额交付签收后才完成协议义务，签收后5日内申请撤执行及解除措施。', 'open': '预计约600万元收益为测算，非600万元现金到账。签约不证明交货签收或法院结案，未履行仍可执行；同批其他诉讼的和解不替代本案履约证据。', 'supporting': [{'source': '1225662648', 'pages': [1, 2], 'state': '11月新增809.33万元诉讼含原告和被告，不能整体当预计损失或代替天府案结案证据。'}]}, {'chain': '600239-抵债房产已备案，距离真正收回还有多远', 'source': '1225610790', 'pages': [1, 2], 'subject': '抵债房产已备案，距离真正收回还有多远', 'changed': '10月披露约24992.10万元资产已网签备案和缴税，过户仍在办理，剩余资产交割推进。', 'open': '整笔29313.57万元对价包含减资现金、房产及股东债权抵偿；未证明全部现金收到或减资完成。全部完成预计约2.44亿元收益有条件，不能直接当已确认利润。22372.76万元债权与22372.36万元资产差额现金补齐属安排，不当已支付。', 'supporting': [{'source': '1225471769', 'pages': [2, 3, 4], 'state': '以债抵债与以物抵债分层；以取得不动产权证书作为相应债权清偿节点。'}]}, {'chain': '600239-审议通过续担保，为什么仍有逾期', 'source': '1225610804', 'pages': [1, 3], 'subject': '审议通过续担保，为什么仍有逾期', 'changed': '老鹰地借款调整后展期及继续担保尚未生效，方案初步一致仍需审议；9月30日逾期担保本金424944448.31元。', 'open': '这笔参股公司借款担保与国寿19.6亿元差额补足义务不同，不能混接或抵销。审议通过不等于协议已生效；尚不能据本件认定代偿已实际发生，亦不证明国寿义务已结清。', 'supporting': []}, {'chain': '600239-归母盈利和经营现金为正，主业已恢复吗', 'source': '1225648868', 'pages': [1], 'subject': '归母盈利和经营现金为正，主业已恢复吗', 'changed': '前三季归母盈利258361805.01元，经营现金128657584.02元；但扣非仍负102912011.61元，收入同比下降27.29%。', 'open': '季度经营现金67810558.49元由累计减半年推算。处置损益与持续经营分开，不能把拟抵债交易2.44亿元预测收益直接接入季报，年度审计与到期义务另核。', 'supporting': [{'source': '1225497032', 'pages': [6], 'state': '半年非流动资产处置损益主要为转让子公司收益，归母正而扣非负。'}]}, {'chain': '600243-增收之后，亏损和现金有没有一起改善', 'source': '1225643194', 'pages': [1], 'subject': '增收之后，亏损和现金有没有一起改善', 'changed': '前三季收入296465649.90元，同比增长50.93%；归母-21732520.87元，扣非-23494691.21元，经营现金-35322036.36元。', 'open': '季度现金-2236681.82元为差额推算，收入增长没有等于盈利现金恢复；前三季普通营收不当全年扣除后营收，不从2.96亿元断言年度门槛结果。', 'supporting': [{'source': '1225478846', 'pages': [5], 'state': '半年归母、扣非和现金仍负，公积金弥补母公司亏损不改变本期经营结果。'}]}, {'chain': '600243-申请之后，正式撤销证据核到了哪里', 'source': '1225478846', 'pages': [5], 'subject': '申请之后，正式撤销证据核到了哪里', 'changed': '本轮取得的半年报、三季报仍列示*ST海华；截至11月19日期间所获目录未找到正式撤销生效原件。', 'open': '未找到不能等同从未发生，也不凭审核期限推自动批准。当前保留正式批准生效证据缺口；旧申请与6月问询延期保留，后续关键回复及年度财务持续核。', 'supporting': [{'source': '1225643194', 'pages': [1], 'state': '三季报证券简称仅作报告时点印证，不代替交易所正式决定。'}]}]
