def followup_view(inputs, prior):
    packet=inputs.get('fifteenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('fifteenth period packet changed')
    if prior is None or prior['counts']['after']!=102 or packet['prior_digest']!=digest(prior):raise ValueError('fifteenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('fifteenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=25 or len(packet['sources'])!=25 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('fifteenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('fifteenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('fifteenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('fifteenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('fifteenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('fifteenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('fifteenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('fifteenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('fifteenth period quarter changed')
        if row['reported_quarter_yuan']is not None and D(row['reported_quarter_yuan'])!=nine-h:raise ValueError('fifteenth period reported quarter changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan'])]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','')
            if any(row[k]not in text for k in keys):raise ValueError('fifteenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('fifteenth period windows changed')
    return {'through':'2026-11-19','title':'摘星、更正和抵债推进后，哪些判断真的改变了？','answer':'椰岛已摘星但继续ST，产品抵债仍须核签收和撤执行；国中扣非更正不产生新现金流出，旧案撤诉与新案冻结分开。云城归母盈利而扣非仍亏，抵债房产备案不等于过户或现金回款，另一参股担保仍有逾期；海华增收仍亏，正式撤销证据缺口保留。','chains':CHAINS,'financial_bridge':FINANCIAL,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':25,'new_files':25,'reused_files':0,'pages':838,'new_pages':838,'viewed_pages':len(VISUAL),'initial_coverage':102,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows']),'stock_endpoint_gaps':sum(w['stock_pct']is None for e in windows for w in e['windows'])},'boundary':'25份838页仅20关键页视觉核，167条期间目录不代表全部催化已穷尽。75窗口64满11未满、2股票空值，73可算收益及70股票端点跨渠道核对，沿用1e-9门槛；旧报价差异及椰岛7月31日空值保持。16半年6报告同比一致、10仅另算（3空白7不适用）；16季度13直接3现金差额。旧年度分类更正不倒填期初，诉请不当已确认损失，股权冻结主体不换成上市公司，抵债和会计收益不当现金回款。海华正式撤销原件未取得不等于认定未发生；全部旧主题、更正及缺口保持，无通用经验晋级，公告同窗不识别净因果。','method_promotions':0}
